UPDATE system_config SET config_value='"Kết nối tri thức học thuật, khảo thí chuẩn hóa và sáng kiến cộng đồng bền vững. Nền tảng chính thức của Trung tâm Nghiên cứu và Phát triển Cộng đồng Sky First."', updated_at=CURRENT_TIMESTAMP WHERE config_key='hero_subtitle_vi' AND config_value IN ('Trung tâm Nghiên cứu và Phát triển Cộng đồng Sky First xây dựng nền tảng tri thức chuẩn mực, thúc đẩy các chương trình nghiên cứu ứng dụng, khảo thí minh bạch và dự án phục vụ cộng đồng bền vững.', '"Trung tâm Nghiên cứu và Phát triển Cộng đồng Sky First xây dựng nền tảng tri thức chuẩn mực, thúc đẩy các chương trình nghiên cứu ứng dụng, khảo thí minh bạch và dự án phục vụ cộng đồng bền vững."');
UPDATE system_config SET config_value='"Connecting academic knowledge, standardized assessment, and sustainable community initiatives. The official platform of Sky First Center for Research and Development."', updated_at=CURRENT_TIMESTAMP WHERE config_key='hero_subtitle_en' AND config_value IN ('Sky First Center for Research and Development builds a rigorous knowledge platform, advancing applied research programs, transparent academic assessment, and sustainable community initiatives.', '"Sky First Center for Research and Development builds a rigorous knowledge platform, advancing applied research programs, transparent academic assessment, and sustainable community initiatives."');
